1	import "server-only";
2	import { clerkClient, verifyToken } from "@clerk/nextjs/server";
3	import { TokenVerificationErrorReason } from "@clerk/backend/errors";
4	import { z } from "zod";
5	import { AgentError, type AgentPrincipal } from "./agent-contract";
6	import { agentHash, matchesApiToken, parseApiToken } from "./api-token-crypto";
7	import { apiEntitlements } from "./api-entitlements";
8	import { hasPermission, requireWorkspaceAccess } from "./authz";
9	import { db } from "./db";
10	import { env } from "./env";
11	import { mcpOAuthConfig } from "./mcp-oauth-metadata";
12	import { mask } from "@/checks/mask";
13	import { selfHostedPlanEnabled } from "./self-hosted-plan";
14	import { syncWorkspacePlan } from "./workspace-plan";
15	
16	export const clientLabel = (v: string) => mask(v).replace(/[\p{Cc}\p{Cf}]/gu, " ").trim().slice(0, 160) || "Agent";
17	export type OAuthIdentity = { userId: string; clientId: string; orgId: string | null; scopes: string[]; issuedAt?: number; expiresAt?: number };
18	const claims = z.object({ sub: z.string().startsWith("user_").max(256), client_id: z.string().min(1).max(2048), iss: z.url(), exp: z.number().int(), iat: z.number().int().optional(), aud: z.union([z.string(), z.array(z.string())]), scope: z.string().optional(), scp: z.array(z.string()).optional(), org_id: z.string().startsWith("org_").max(256).optional() });
19	const invalidReasons = new Set<string>([
20	  TokenVerificationErrorReason.TokenExpired, TokenVerificationErrorReason.TokenInvalid,
21	  TokenVerificationErrorReason.TokenInvalidAlgorithm, TokenVerificationErrorReason.TokenInvalidAuthorizedParties,
22	  TokenVerificationErrorReason.TokenInvalidSignature, TokenVerificationErrorReason.TokenNotActiveYet,
23	  TokenVerificationErrorReason.TokenIatInTheFuture, TokenVerificationErrorReason.TokenVerificationFailed,
24	  TokenVerificationErrorReason.JWKKidMismatch,
25	]);
26	const unavailable = () => new AgentError(503, "authorization_unavailable", "Authorization could not be checked. Try again later.");
27	const invalid = () => new AgentError(401, "invalid_token", "Sign in through your MCP client or supply a valid workspace API token.");
28	/** The unverified header only gates a bounded key-list read, never identity. Random kids
29	 * cannot turn every anonymous request into a Clerk Backend API call. */
30	export function createOAuthVerifier(loadKeys = async () => ((await (await clerkClient()).jwks.getJwks()).keys ?? []).map(k => k.kid), now = Date.now) {
31	  let keys = new Set<string>(); let refreshed = -Infinity; let failed = false; let loading: Promise<void> | null = null;
32	  return async (token: string): Promise<OAuthIdentity | null> => {
33	    if (token.length > 16384 || token.split(".").length !== 3) return null;
34	    let kid: unknown;
35	    try { kid = JSON.parse(Buffer.from(token.split(".")[0], "base64url").toString()).kid; } catch { return null; }
36	    if (typeof kid !== "string" || !kid || kid.length > 256) return null;
37	    if (!keys.has(kid)) {
38	      if (now() - refreshed >= 60000) {
39	        loading ??= loadKeys().then(ids => { keys = new Set(ids); failed = false; }, () => { failed = true; }).finally(() => { refreshed = now(); loading = null; });
40	        await loading;
41	      } else if (loading) await loading;
42	      if (failed) throw unavailable();
43	      if (!keys.has(kid)) return null;
44	    }
45	    const { resource, issuer } = mcpOAuthConfig();
46	    let payload: unknown;
47	    try { payload = await verifyToken(token, { secretKey: env().CLERK_SECRET_KEY, audience: resource, headerType: ["at+jwt", "application/at+jwt"], clockSkewInMs: 5000 }); }
48	    catch (e) {
49	      if (e && typeof e === "object" && "reason" in e && invalidReasons.has(String(e.reason))) return null;
50	      throw unavailable();
51	    }
52	    const p = claims.safeParse(payload);
53	    if (!p.success || p.data.iss !== issuer || ![p.data.aud].flat().includes(resource) || p.data.exp <= Math.floor(now() / 1000)) return null;
54	    return { userId: p.data.sub, clientId: p.data.client_id, orgId: p.data.org_id ?? null, scopes: p.data.scp ?? p.data.scope?.split(/\s+/) ?? [], issuedAt: p.data.iat, expiresAt: p.data.exp };
55	  };
56	}
57	export async function spendAgentBudget(key: string, limit: number) {
58	  const { data, error } = await db().rpc("agent_budget", { p_key: key, p_limit: limit });
59	  if (error) throw new AgentError(503, "temporarily_unavailable", "The request budget could not be checked. Try again later.");
60	  if (data > 0) throw new AgentError(429, "rate_limited", "Too many calls. Try again after the indicated delay.", data);
61	}
62	export const authDependencies = {
63	  verify: createOAuthVerifier(),
64	  async membershipRole(orgId: string, userId: string) {
65	    try {
66	      const r = await (await clerkClient()).organizations.getOrganizationMembershipList({ organizationId: orgId, userId: [userId], limit: 1 });
67	      return r.data.find(x => x.organization.id === orgId && x.publicUserData?.userId === userId)?.role ?? null;
68	    } catch (e) { if (e && typeof e === "object" && "status" in e && e.status === 404) return null; throw unavailable(); }
69	  },
70	  async clientName(clientId: string) {
71	    // OAuth's verified client id is always kept beside the display name. A client cannot
72	    // impersonate another grant by supplying initialize/clientInfo or an HTTP header.
73	    try {
74	      // client_id is not Clerk's oauthapp_ id. Lookup by exact client id and check it
75	      // again because nameQuery can also match another application's display name.
76	      const applications = await (await clerkClient()).oauthApplications.list({ nameQuery: clientId, limit: 100 });
77	      const app = applications.data.find(a => a.clientId === clientId);
78	      return app ? `${clientLabel(app.name)} (${clientLabel(clientId)})` : clientLabel(clientId);
79	    }
80	    catch { return clientLabel(clientId); }
81	  },
82	  entitlements: apiEntitlements,
83	  budget: spendAgentBudget,
84	};
85	export type SeenAgent = (principal: Pick<AgentPrincipal, "actor" | "auth" | "client"> & { workspace?: AgentPrincipal["workspace"]; grant?: Pick<OAuthIdentity, "clientId" | "scopes" | "issuedAt" | "expiresAt"> }) => void;
86	export async function requireAgent(request: Request, oauth: boolean, seen?: SeenAgent, deps = authDependencies): Promise<AgentPrincipal> {
87	  const header = request.headers.get("authorization");
88	  const pepper = env().API_TOKEN_PEPPER;
89	  let principal: Omit<AgentPrincipal, "entitlements">;
90	  let storedPlan: string;
91	  if (/^Bearer\s+sg_/i.test(header ?? "")) {
92	    const token = parseApiToken(header);
93	    if (!token) throw invalid();
94	    const { data, error } = await db().from("api_tokens").select("id,workspace_id,hash,scope,name,revoked_at").eq("kid", token.kid).maybeSingle();
95	    if (error) throw unavailable();
96	    const matches = matchesApiToken(data?.workspace_id ?? "", token.secret, data?.hash ?? "", pepper);
97	    if (!data || !matches || data.revoked_at !== null) throw invalid();
98	    const owner = await db().from("workspaces").select("id,clerk_org_id,plan").eq("id", data.workspace_id).single();
99	    if (owner.error) throw unavailable();
100	    storedPlan = owner.data.plan;
101	    principal = { workspace: { id: owner.data.id, clerk_org_id: owner.data.clerk_org_id }, actor: data.id, client: clientLabel(data.name), scope: data.scope, auth: "api_token" };
102	    seen?.(principal);
103	    await deps.budget(agentHash("admission-token", data.workspace_id, pepper), 120);
104	    const touched = await db().from("api_tokens").update({ last_used_at: new Date().toISOString() }).eq("id", data.id).is("revoked_at", null).or(`last_used_at.is.null,last_used_at.lt.${new Date(Date.now() - 60000).toISOString()}`);
105	    if (touched.error) throw unavailable();
106	  } else {
107	    if (!oauth) throw new AgentError(401, "invalid_token", "REST requires a workspace API token. OAuth access tokens are accepted only at /mcp.");
108	    const bearer = /^Bearer ([^\s]+)$/i.exec(header ?? "");
109	    const identity = bearer ? await deps.verify(bearer[1]) : null;
110	    if (!identity) throw invalid();
111	    const actor = agentHash("oauth-actor", [identity.orgId, identity.userId, identity.clientId], pepper);
112	    seen?.({ actor, auth: "oauth", client: clientLabel(identity.clientId), grant: identity });
113	    // Before live membership, and before ensure_workspace: refused members and brand new
114	    // users count too. Client registration and token refresh cannot reset this user bucket.
115	    await deps.budget(agentHash("admission-oauth", identity.userId, pepper), 120);
116	    if (!identity.orgId) throw new AgentError(403, "organization_required", "Select a workspace when granting access. Reconnect with user:org:read.");
117	    if (!identity.scopes.includes("user:org:read")) throw new AgentError(403, "insufficient_scope", "Reconnect with user:org:read and select a workspace.");
118	    const caller = { userId: identity.userId, orgId: identity.orgId, orgRole: await deps.membershipRole(identity.orgId, identity.userId) };
119	    const ref = { id: "", clerk_org_id: identity.orgId };
120	    if (!hasPermission(ref, caller, "monitors:read")) throw new AgentError(403, "admin_required", "Your current membership does not allow access to this workspace.");
121	    const { data, error } = await db().rpc("ensure_workspace", { p_clerk_org_id: identity.orgId });
122	    if (error || !data) throw unavailable();
123	    const workspace = { id: data.id, clerk_org_id: data.clerk_org_id };
124	    storedPlan = data.plan;
125	    requireWorkspaceAccess(workspace, caller, "monitors:read");
126	    principal = { workspace, actor, scope: "write", auth: "oauth", client: clientLabel(await deps.clientName(identity.clientId)) };
127	  }
128	  seen?.(principal);
129	  const entitlements = await deps.entitlements(principal.workspace.clerk_org_id);
130	  await deps.budget(agentHash("workspace", principal.workspace.id, pepper), entitlements.limits.apiPerMin);
131	  // MCP can create a workspace before its first dashboard visit. In self-hosted mode it must
132	  // reach Builder-only probes too. Hosted billing keeps its existing member-session sync;
133	  // a failed machine billing read there is Free, not evidence for downgrading the stored plan.
134	  if (selfHostedPlanEnabled()) {
135	    await syncWorkspacePlan(principal.workspace.id, storedPlan, "builder");
136	  }
137	  return { ...principal, entitlements };
138	}
