1	import "server-only";
2	import { z } from "zod";
3	import { tokenInput } from "./agent-contract";
4	import { agentHash, newApiToken } from "./api-token-crypto";
5	import { requireWorkspaceAccess } from "./authz";
6	import { spendAgentBudget } from "./agent-auth";
7	import { db } from "./db";
8	import { env } from "./env";
9	import type { Member } from "./workspace";
10	
11	const SUMMARY="id,name,kid,scope,created_at,last_used_at,revoked_at";
12	export type TokenSummary={id:string;name:string;kid:string;scope:"read"|"write";created_at:string;last_used_at:string|null;revoked_at:string|null};
13	export type AgentActivity={id:string;client:string;tool:string;resource_id:string;created_at:string};
14	export async function agentSettings(member:Member) {
15	  requireWorkspaceAccess(member.workspace,member.caller,"monitors:read");
16	  const {data:activity,error}=await db().from("agent_activity").select("id,client,tool,resource_id,created_at").eq("workspace_id",member.workspace.id).order("created_at",{ascending:false}).order("id").limit(100);
17	  if(error) throw new Error("Activity could not be loaded");
18	  const {hasPermission}=await import("./authz");
19	  let tokens:TokenSummary[]=[];
20	  if(hasPermission(member.workspace,member.caller,"tokens:manage")) {
21	    const r=await db().from("api_tokens").select(SUMMARY).eq("workspace_id",member.workspace.id).is("revoked_at",null).order("created_at",{ascending:false}).limit(100);
22	    if(r.error) throw new Error("Tokens could not be loaded"); tokens=r.data??[];
23	  }
24	  return {tokens,activity:activity??[]};
25	}
26	export async function mintApiToken(member:Member,input:unknown) {
27	  requireWorkspaceAccess(member.workspace,member.caller,"tokens:manage");
28	  const a=tokenInput.parse(input);const pepper=env().API_TOKEN_PEPPER;
29	  await spendAgentBudget(agentHash("token-management",[member.workspace.id,member.caller.userId],pepper),10);
30	  const token=newApiToken(member.workspace.id,pepper);
31	  const id=`tok_${a.request_id.replaceAll("-","").slice(0,24)}`;
32	  const {error}=await db().rpc("agent_token_create",{p_workspace_id:member.workspace.id,p_id:id,p_name:a.name,p_kid:token.kid,p_hash:token.hash,p_scope:a.scope});
33	  if(error) {
34	    if(error.code==="23505") return {ok:false,reason:"This token was already created. If you missed its value, revoke it and create another."} as const;
35	    if(error.message==="token_limit") return {ok:false,reason:"This workspace has 100 active tokens. Revoke one before creating another."} as const;
36	    throw new Error("Token creation failed");
37	  }
38	  return {ok:true,token:token.plaintext} as const;
39	}
40	export async function revokeApiToken(member:Member,tokenId:string) {
41	  requireWorkspaceAccess(member.workspace,member.caller,"tokens:manage");
42	  const id=z.string().regex(/^tok_[0-9a-f]{24}$/).parse(tokenId);
43	  const {data,error}=await db().from("api_tokens").update({revoked_at:new Date().toISOString()}).eq("workspace_id",member.workspace.id).eq("id",id).select("id");
44	  if(error) throw new Error("Token revocation failed");
45	  return data?.length?{ok:true} as const:{ok:false,reason:"That token isn't here any more."} as const;
46	}
