  await spendAgentBudget(agentHash("token-management",[member.workspace.id,member.caller.userId],pepper),10);
  const token=newApiToken(member.workspace.id,pepper);
  const id=`tok_${a.request_id.replaceAll("-","").slice(0,24)}`;
