152	  const input = inputs[tool].parse(raw) as {request_id:string};
153	  const hash = fingerprint(tool,input);
154	  const prior = await db().from("agent_requests").select("input_hash,tool,result").eq("workspace_id",p.workspace.id).eq("actor",p.actor).eq("request_id",input.request_id).maybeSingle();
155	  if(prior.error) dbFailure(prior.error);
156	  if(prior.data) {
157	    if(prior.data.input_hash !== hash || prior.data.tool !== tool) throw new AgentError(409,"request_conflict","That request_id was already used with different inputs.");
158	    return writeResult(tool,prior.data.result);
159	  }
